br(e($row['customer_address'])); ?></p></div><div class="box"><div><b>Tarih</b><span><?php echo e(tr_date($row['dispatch_date'])); ?></span></div><div><b>Fiş No</b><span><?php echo e($row['dispatch_no']); ?></span></div></div></section><table><thead><tr><th>Barkod</th><th>Ürün</th><th>Açıklama</th><th>Miktar</th><th>Birim Fiyat</th><th>Tutar</th></tr></thead><tbody><?php foreach($row['items'] as $i): ?><tr><td><?php echo e($i['product_barcode']); ?></td><td><?php echo e($i['product_name']); ?></td><td><?php echo e($i['product_type']); ?></td><td class="num"><?php echo e(number_format((float)$i['quantity'],0,',','.')); ?></td><td class="num"><?php echo e(money((float)$i['unit_price'])); ?></td><td class="num"><?php echo e(money((float)$i['line_total'])); ?></td></tr><?php endforeach; ?></tbody></table><div class="totals"><div class="total-row"><span>Ara Toplam:</span><strong><?php echo e(money((float)($row['subtotal']??$row['total']))); ?> TL</strong></div><?php if((int)($row['discount_enabled']??0)===1): ?><div class="total-row discount"><span>İskonto (%<?php echo e((string)($row['discount_rate']??0)); ?>):</span><strong>-<?php echo e(money((float)($row['discount_amount']??0))); ?> TL</strong></div><?php endif; ?><?php if((int)($row['vat_enabled']??0)===1): ?><div class="total-row"><span>KDV (%<?php echo e((string)($row['vat_rate']??0)); ?>):</span><strong><?php echo e(money((float)($row['vat_amount']??0))); ?> TL</strong></div><?php endif; ?><div class="total-row grand"><span>GENEL TOPLAM:</span><strong><?php echo e(money((float)$row['total'])); ?> TL</strong></div></div><?php if(trim((string)$row['note'])!==''): ?><div class="note"><b>NOT:</b> <?php echo nl2br(e($row['note'])); ?></div><?php endif; ?></main></body></html>
